<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #0d0d0d;
    color: #e0e0e0;
    font-family: system-ui, -apple-system, sans-serif;
    padding: 20px;
  }
  h1 {
    font-size: clamp(1.5rem, 4vw, 2.5rem);
    margin-bottom: 16px;
    font-weight: 700;
    letter-spacing: -0.02em;
    background: linear-gradient(135deg, #00ff88, #00ccff);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  #life {
    background: #1a1a1a;
    border: 2px solid #333;
    border-radius: 8px;
    box-shadow: 
      0 0 0 1px #2a2a2a,
      0 20px 40px -10px rgba(0,0,0,0.8),
      inset 0 0 60px rgba(0,0,0,0.5);
    cursor: crosshair;
    touch-action: none;
  }
  #life:hover { border-color: #00ff88; }
  .controls {
    display: flex;
    gap: 12px;
    margin-top: 20px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    padding: 12px 24px;
    font-size: 14px;
    font-weight: 600;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }
  button:focus-visible { outline: 2px solid #00ff88; outline-offset: 2px; }
  #step { background: #2a2a2a; color: #e0e0e0; border: 1px solid #444; }
  #step:hover { background: #333; border-color: #555; }
  #step:active { background: #1a1a1a; }
  #play { background: linear-gradient(135deg, #00ff88, #00cc66); color: #0d0d0d; }
  #play:hover { filter: brightness(1.1); transform: translateY(-1px); }
  #play:active { transform: translateY(0); }
  #play.running { background: linear-gradient(135deg, #ff4444, #cc3333); }
  #random { background: #2a2a2a; color: #e0e0e0; border: 1px solid #444; }
  #random:hover { background: #333; border-color: #555; }
  #clear { background: #2a2a2a; color: #e0e0e0; border: 1px solid #444; }
  #clear:hover { background: #333; border-color: #555; }
  .stats {
    margin-top: 16px;
    font-size: 13px;
    color: #888;
    font-family: ui-monospace, monospace;
  }
  .stats span { color: #00ff88; font-weight: 600; }
  @media (max-width: 520px) {
    #life { width: 100%; max-width: 400px; height: auto; }
    button { padding: 10px 16px; font-size: 12px; }
  }
</style>
</head>
<body>
<h1>Conway's Game of Life</h1>
<canvas id="life" width="500" height="500"></canvas>
<div class="controls">
  <button id="step">Step</button>
  <button id="play">Play</button>
  <button id="random">Random</button>
  <button id="clear">Clear</button>
</div>
<div class="stats">Generation: <span id="gen">0</span> | Alive: <span id="alive">0</span></div>

<script>
const CELL_SIZE = 10;
const GRID_W = 50;
const GRID_H = 50;
const CANVAS_SIZE = 500;

const canvas = document.getElementById('life');
const ctx = canvas.getContext('2d');
const stepBtn = document.getElementById('step');
const playBtn = document.getElementById('play');
const randomBtn = document.getElementById('random');
const clearBtn = document.getElementById('clear');
const genEl = document.getElementById('gen');
const aliveEl = document.getElementById('alive');

let current = new Uint8Array(GRID_W * GRID_H);
let next = new Uint8Array(GRID_W * GRID_H);
let generation = 0;
let running = false;
let animationId = null;
let isDrawing = false;
let lastToggled = null;

function idx(x, y) { return y * GRID_W + x; }

function get(x, y) {
  if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return 0;
  return current[idx(x, y)];
}

function set(x, y, v) {
  if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return;
  current[idx(x, y)] = v ? 1 : 0;
}

function countNeighbors(x, y) {
  let count = 0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const nx = x + dx, ny = y + dy;
      if (nx >= 0 && nx < GRID_W && ny >= 0 && ny < GRID_H) {
        count += current[idx(nx, ny)];
      }
    }
  }
  return count;
}

function step() {
  for (let y = 0; y < GRID_H; y++) {
    for (let x = 0; x < GRID_W; x++) {
      const i = idx(x, y);
      const cell = current[i];
      const neighbors = countNeighbors(x, y);
      if (cell) {
        next[i] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
      } else {
        next[i] = (neighbors === 3) ? 1 : 0;
      }
    }
  }
  [current, next] = [next, current];
  generation++;
  draw();
  updateStats();
}

function draw() {
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

  ctx.fillStyle = '#00ff88';
  for (let y = 0; y < GRID_H; y++) {
    for (let x = 0; x < GRID_W; x++) {
      if (current[idx(x, y)]) {
        ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE - 1, CELL_SIZE - 1);
      }
    }
  }

  ctx.strokeStyle = '#2a2a2a';
  ctx.lineWidth = 0.5;
  for (let i = 0; i <= GRID_W; i++) {
    ctx.beginPath();
    ctx.moveTo(i * CELL_SIZE, 0);
    ctx.lineTo(i * CELL_SIZE, CANVAS_SIZE);
    ctx.stroke();
  }
  for (let i = 0; i <= GRID_H; i++) {
    ctx.beginPath();
    ctx.moveTo(0, i * CELL_SIZE);
    ctx.lineTo(CANVAS_SIZE, i * CELL_SIZE);
    ctx.stroke();
  }
}

function updateStats() {
  let alive = 0;
  for (let i = 0; i < current.length; i++) alive += current[i];
  genEl.textContent = generation;
  aliveEl.textContent = alive;
}

function clear() {
  current.fill(0);
  generation = 0;
  draw();
  updateStats();
}

function randomize() {
  for (let i = 0; i < current.length; i++) {
    current[i] = Math.random() < 0.3 ? 1 : 0;
  }
  generation = 0;
  draw();
  updateStats();
}

function toggleCell(x, y) {
  const cx = Math.floor(x / CELL_SIZE);
  const cy = Math.floor(y / CELL_SIZE);
  if (cx < 0 || cx >= GRID_W || cy < 0 || cy >= GRID_H) return;
  const key = cx + ',' + cy;
  if (key === lastToggled) return;
  lastToggled = key;
  current[idx(cx, cy)] ^= 1;
  draw();
  updateStats();
}

function getCanvasCoords(e) {
  const rect = canvas.getBoundingClientRect();
  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
  const clientY = e.touches ? e.touches[0].clientY : e.clientY;
  return {
    x: clientX - rect.left,
    y: clientY - rect.top
  };
}

canvas.addEventListener('mousedown', e => {
  isDrawing = true;
  lastToggled = null;
  const {x, y} = getCanvasCoords(e);
  toggleCell(x, y);
});

canvas.addEventListener('mousemove', e => {
  if (!isDrawing) return;
  const {x, y} = getCanvasCoords(e);
  toggleCell(x, y);
});

window.addEventListener('mouseup', () => { isDrawing = false; lastToggled = null; });

canvas.addEventListener('touchstart', e => {
  e.preventDefault();
  isDrawing = true;
  lastToggled = null;
  const {x, y} = getCanvasCoords(e);
  toggleCell(x, y);
}, { passive: false });

canvas.addEventListener('touchmove', e => {
  e.preventDefault();
  if (!isDrawing) return;
  const {x, y} = getCanvasCoords(e);
  toggleCell(x, y);
}, { passive: false });

canvas.addEventListener('touchend', () => { isDrawing = false; lastToggled = null; });

stepBtn.addEventListener('click', step);

playBtn.addEventListener('click', () => {
  running = !running;
  playBtn.textContent = running ? 'Pause' : 'Play';
  playBtn.classList.toggle('running', running);
  if (running) {
    const loop = () => {
      if (!running) return;
      step();
      animationId = requestAnimationFrame(loop);
    };
    animationId = requestAnimationFrame(loop);
  } else {
    cancelAnimationFrame(animationId);
  }
});

randomBtn.addEventListener('click', randomize);
clearBtn.addEventListener('click', clear);

window.life = {
  w: GRID_W,
  h: GRID_H,
  get,
  set,
  step,
  clear
};

draw();
updateStats();
</script>
</body>
</html>
